import { getAudioContext, musicEnabled } from "./audio.js";
export function playJumpSound(){if(!getAudioContext()||!musicEnabled)return;const a=getAudioContext(),o=a.createOscillator(),g=a.createGain();o.type='sine';o.frequency.setValueAtTime(300,a.currentTime);o.frequency.exponentialRampToValueAtTime(600,a.currentTime+.15);g.gain.setValueAtTime(.2,a.currentTime);g.gain.exponentialRampToValueAtTime(.001,a.currentTime+.2);o.connect(g).connect(a.destination);o.start();o.stop(a.currentTime+.2);}
export function playDoubleJumpSound(){if(!getAudioContext()||!musicEnabled)return;const a=getAudioContext(),o=a.createOscillator(),g=a.createGain();o.type='sine';o.frequency.setValueAtTime(500,a.currentTime);o.frequency.exponentialRampToValueAtTime(900,a.currentTime+.2);g.gain.setValueAtTime(.25,a.currentTime);g.gain.exponentialRampToValueAtTime(.001,a.currentTime+.25);o.connect(g).connect(a.destination);o.start();o.stop(a.currentTime+.25);}
export function playCloudBreakSound(){if(!getAudioContext()||!musicEnabled)return;}
export function playThunderSound(){if(!getAudioContext()||!musicEnabled)return;const a=getAudioContext(),o=a.createOscillator(),g=a.createGain();o.type='sine';o.frequency.setValueAtTime(60,a.currentTime);o.frequency.exponentialRampToValueAtTime(30,a.currentTime+.5);g.gain.setValueAtTime(.4,a.currentTime);g.gain.exponentialRampToValueAtTime(.001,a.currentTime+1);o.connect(g).connect(a.destination);o.start();o.stop(a.currentTime+1);const nbs=a.sampleRate*.8,buf=a.createBuffer(1,nbs,a.sampleRate),d=buf.getChannelData(0);for(let i=0;i<nbs;i++)d[i]=Math.random()*2-1;const n=a.createBufferSource();n.buffer=buf;const f=a.createBiquadFilter();f.type='lowpass';f.frequency.value=200;const ng=a.createGain();ng.gain.setValueAtTime(.3,a.currentTime);ng.gain.exponentialRampToValueAtTime(.001,a.currentTime+.8);n.connect(f).connect(ng).connect(a.destination);n.start();n.stop(a.currentTime+.8);}
